#include "voxel/app.h"
#include "voxel/classic_ui.h"
#include "../common/virtual_keyboard.h"
struct editor_state{char path[VOXEL_APP_PATH_MAX];char text[VOXEL_APP_TEXT_MAX];uint32_t length;};
static struct editor_state*st(struct voxel_app_context*a){return(struct editor_state*)a->state;}
void voxel_editor_init(struct voxel_app_context*a){struct editor_state*s=st(a);s->path[0]=0;s->length=0;s->text[0]=0;}
void voxel_editor_draw(struct voxel_app_context*a){struct editor_state*s=st(a);voxel_surface_clear(a->surface,VOXEL_UI_FACE);voxel_ui_window_frame(a->surface, (struct voxel_ui_rect){2,2,(int32_t)a->surface->width-4,(int32_t)a->surface->height-4}, "Text Editor", 1);voxel_ui_button(a->surface,(struct voxel_ui_rect){12,30,50,18},"SAVE",0);voxel_ui_button(a->surface,(struct voxel_ui_rect){68,30,50,18},"OPEN",0);voxel_ui_text(a->surface,124,34,s->path[0]?s->path:"UNTITLED",VOXEL_UI_TEXT);voxel_ui_bevel(a->surface,(struct voxel_ui_rect){10,52,(int32_t)a->surface->width-20,(int32_t)a->surface->height-64},1);voxel_ui_text(a->surface,16,60,s->text,VOXEL_UI_TEXT);voxel_vk_draw(a->surface,(int32_t)a->surface->height-100);}
int voxel_editor_key(struct voxel_app_context*a,uint32_t k){struct editor_state*s=st(a);if(k==8u&&s->length){s->text[--s->length]=0;return 1;}if(k>=32&&k<127&&s->length+1<sizeof(s->text)){s->text[s->length++]=(char)k;s->text[s->length]=0;return 1;}return 0;}
int voxel_editor_pointer(struct voxel_app_context*a,int32_t x,int32_t y){struct editor_state*s=st(a);uint32_t key=0,len=s->length;if(y>=30&&y<48&&x>=12&&x<62){return s->path[0]?voxel_editor_save(a,s->path):voxel_editor_new(a,"/notes.txt");}if(y>=30&&y<48&&x>=68&&x<118){return voxel_editor_load(a,s->path[0]?s->path:"/etc/version");}if(y>=(int32_t)a->surface->height-100&&voxel_vk_pointer(a->surface,x,y,(int32_t)a->surface->height-100,s->text,sizeof(s->text),&len,&key)){s->length=len;return 1;}return 0;}
int voxel_editor_new(struct voxel_app_context*a,const char*path){struct editor_state*s=st(a);uint32_t i;if(!path)return -1;for(i=0;path[i]&&i<sizeof(s->path)-1;i++)s->path[i]=path[i];s->path[i]=0;s->length=0;s->text[0]=0;return 0;}
int voxel_editor_save(struct voxel_app_context*a,const char*path){struct editor_state*s=st(a);if(!a->host||!a->host->write_file||!path)return -1;return a->host->write_file(a->host->userdata,path,s->text,s->length);}
int voxel_editor_load(struct voxel_app_context*a,const char*path){struct editor_state*s=st(a);uint32_t n=0,i;if(!a->host||!a->host->read_file||!path)return -1;if(a->host->read_file(a->host->userdata,path,s->text,sizeof(s->text)-1,&n))return -1;if(n>=sizeof(s->text))return -1;for(i=0;i<n;i++)if(!s->text[i])s->text[i]='?';s->text[n]=0;s->length=n;for(i=0;path[i]&&i<sizeof(s->path)-1;i++)s->path[i]=path[i];s->path[i]=0;return 0;}
